-- string.format: every conversion with widths, precisions and flags, %q, %s with non-strings, %% and errors.
local f = string.format
print(f("%d %i %u", 42, -42, 42), f("%5d|%-5d|%05d|%+d|% d", 42, 42, 42, 42, 42), f("%.3d|%8.3d|%-8.3d|", 5, 5, 5))
print(f("%d", 3.9), f("%d", -3.9), f("%d", "12"), f("%d", 2^31), f("%d", -2^31), f("%d", 2^53), f("%i", 1e10))
print(f("%x %X %o %#x %#X %#o", 255, 255, 8, 255, 255, 8), f("%08x|%-8x|%8x", 255, 255, 255), f("%x", 0), f("%.4x", 255))
print(f("%x", -1) == f("%x", 4294967295) or f("%x", -1), f("%c%c%c", 76, 117, 97), f("%c", 0) == "\0", #f("%5c", 65))
print(f("%e", 12345.6789), f("%E", 0.000123), f("%.0e", 12345.6789), f("%.2e", 0), f("%10.3e|", 1), f("%-12.2e|", -1.5), f("%e", 1e100))
print(f("%f", 3.14159), f("%.2f", 3.14159), f("%.0f", 2.5), f("%.0f", 3.5), f("%.0f", -0.5), f("%10.3f|", 3.14159), f("%-10.3f|", 3.14159), f("%010.3f", -3.14159))
print(f("%+.1f", 2), f("% .1f", 2), f("%#.0f", 3), f("%.10f", 1/3), f("%f", 1e15), f("%f", 0), f("%.3f", 2/3), f("%.1f", 0.05), f("%.1f", 0.25))
print(f("%g", 100000), f("%g", 1000000), f("%g", 1e-4), f("%g", 1e-5), f("%g", 0.5), f("%g", 123456789), f("%g", 1.5e300), f("%G", 1e-10), f("%g", 0))
print(f("%.3g", 3.14159), f("%.10g", 1/3), f("%.14g", 0.1), f("%.17g", 0.1), f("%10g|", 1.5), f("%-10g|", 1.5), f("%#g", 1), f("%.0g", 15), f("%+g", 1))
print(f("%s", "str"), f("%s", 12), f("%s", 1.5), f("%s", true), f("%s", nil), f("%10s|", "hi"), f("%-10s|", "hi"), f("%.2s", "hello"), f("%5.1s|", "xyz"))
print(f("%s %s", 1, 2), f("%s", 1e100), f("%s", 0/0 ~= 0/0), f("%s", -0.0), f("%s", 2^53), f("%.3s", 12345))
print(f("%q", "plain"), f("%q", 'quote"s'), f("%q", "back\\slash"), f("%q", "new\nline"), f("%q", "tab\t"), f("%q", "nul\0byte"), f("%q", "\r"))
print(f("%q", ""), f("%q", "\1\2\3"), f("%q", "\200\255"), f("%q", 42), f("%q", 1.5))
print(f(""), f("no specs"), f("%s", ""), f("a%sb", "-"), #f("%99d", 1), #f("%.99f", 1))
print(f("%s=%d (%5.2f%%)", "ratio", 3, 45.678))
print(f("%3d|%-3d|%03d", 12345, 12345, 12345))
print(f("%.20s", "short"), f("%.0s", "gone") == "", f("%s", "a\0b") == "a\0b", #f("%s", "a\0b"))
print(f("%5s|%-5s|", "toolongvalue", "toolongvalue"))
print(pcall(f, "%d", "x") == false, pcall(f, "%d", nil) == false, pcall(f, "%d", {}) == false, pcall(f, "%s") == false, pcall(f, "%y", 1) == false)
print(pcall(f, "%", 1) == false, pcall(f, "%d") == false, pcall(f, "%0", 1) == false, pcall(f, "%100d", 1) == false, pcall(f, "%.100f", 1) == false)
print(f("%d", 0/0) == f("%d", 0/0), f("%f", 1/0), f("%f", -1/0), f("%5.1f", 0/0 * 0), f("%g", 1/0), f("%e", -1/0), f("%x", 3.0))
